questionvariables.text:
/* Randomising question form */
angTypeA:rand(["elevation","depression"]);
angTypeB:if angTypeA="elevation" then "depression" else if angTypeA="depression" then "elevation";

/* Randomising the measurements */
angInit:rand_with_prohib(1,5,[3])*10;
distInit:rand_with_step(300,600,10);
distChange:rand_with_step(100,200,10);

/* Solutions */
tans1:distInit*sin(angInit*%pi/180);

tansA2:atan(tans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi;
tansB2:atan(round(tans1)/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi;

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Correct answer, incorrect rounding (1) */
node3_test: if abs(ans1-tans1)<=1 then 1 else 0;

/* Node 4: Uses tan or cos instead of sin */
node4_test: if abs(ans1-distInit/sin(angInit*%pi/180))<=1 or abs(ans1-distInit*cos(angInit*%pi/180))<=1 or abs(ans1-distInit/cos(angInit*%pi/180))<=1 or abs(ans1-distInit*tan(angInit*%pi/180))<=1 or abs(ans1-distInit/tan(angInit*%pi/180))<=1 then 1 else 0;

/* Node 1: Correct answer */
node1_test: if ans2=decimalplaces(tansA2,2) or ans2=decimalplaces(tansB2,2) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: ECF (4) */
node3_test: if ans2=decimalplaces(atan(ans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi,2)  then 1 else 0;

/* Node 4: Correct answer, incorrectly rounded (3) */
node4_test: if abs(ans2-tansA2)<=0.1 or abs(ans2-tansB2)<=0.1 then 1 else 0;

/* Node 5: ECF, incorrectly rounded (3) */
node5_test: if abs(ans2-(atan(ans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi))<=0.1 then 1 else 0;

/* Node 6: Uses one trig function incorrectly (2) */
node6_test: if abs(ans2-(atan(ans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(atan(tans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(atan(ans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(atan(tans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(atan((distInit*sin(angInit*%pi/180)+distChange)/ans1)*180/%pi))<=0.01 or abs(ans2-(atan((distInit*sin(angInit*%pi/180)+distChange)/tans1)*180/%pi))<=0.01 or abs(ans2-(atan((distInit*tan(angInit*%pi/180)+distChange)/ans1)*180/%pi))<=0.01 or abs(ans2-(atan((distInit*tan(angInit*%pi/180)+distChange)/tans1)*180/%pi))<=0.01 or abs(ans2-(asin(ans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(asin(tans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(acos(ans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(acos(tans1/(distInit*cos(angInit*%pi/180)+distChange))*180/%pi))<=0.01 or abs(ans2-(asin((distInit*cos(angInit*%pi/180)+distChange)/ans1)*180/%pi))<=0.01 or abs(ans2-(asin((distInit*cos(angInit*%pi/180)+distChange)/tans1)*180/%pi))<=0.01 or abs(ans2-(acos((distInit*cos(angInit*%pi/180)+distChange)/ans1)*180/%pi))<=0.01 or abs(ans2-(acos((distInit*cos(angInit*%pi/180)+distChange)/tans1)*180/%pi))<=0.01 then 1 else 0;

/* Node 7: Uses both trig functions incorrectly (1) */
node7_test: if abs(ans2-acos(ans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-acos(tans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-acos(ans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-acos(tans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-asin(ans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-asin(tans1/(distInit*sin(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-asin(ans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-asin(tans1/(distInit*tan(angInit*%pi/180)+distChange))*180/%pi)<=0.01 or abs(ans2-acos((distInit*sin(angInit*%pi/180)+distChange)/ans1)*180/%pi)<=0.01 or abs(ans2-acos((distInit*sin(angInit*%pi/180)+distChange)/tans1)*180/%pi)<=0.01 or abs(ans2-acos((distInit*tan(angInit*%pi/180)+distChange)/ans1)*180/%pi)<=0.01 or abs(ans2-acos((distInit*tan(angInit*%pi/180)+distChange)/tans1)*180/%pi)<=0.01 or abs(ans2-asin((distInit*sin(angInit*%pi/180)+distChange)/ans1)*180/%pi)<=0.01 or abs(ans2-asin((distInit*sin(angInit*%pi/180)+distChange)/tans1)*180/%pi)<=0.01 or abs(ans2-asin((distInit*tan(angInit*%pi/180)+distChange)/ans1)*180/%pi)<=0.01 or abs(ans2-asin((distInit*tan(angInit*%pi/180)+distChange)/tans1)*180/%pi)<=0.01 then 1 else 0;
